<template><section aria-label="本次教学任务的已核反馈"><p v-if="error" role="alert">{{error}}</p><p v-if="busy" role="status">正在核对本次练习与讲解。</p><template v-if="view"><h3>教学反馈草稿</h3><p>任务{{view.metadata.run_id}}；状态：{{states[view.metadata.status]}}。教学说明不改变服务端练习记录，不代表诊疗、能力或资质认证。</p><p v-if="view.metadata.usage" aria-label="实际独立用量">输入计数：{{count(view.metadata.usage.input_tokens)}}；输出计数：{{count(view.metadata.usage.output_tokens)}}；模型调用：{{attempt(view.metadata.usage.model_call_attempted)}}。缺失计数不等于零费用。</p><p v-else>用量回执：{{view.metadata.receipt_pending?'原在途请求尚待实际回执，未知用量':'尚无实际用量回执'}}。</p><p v-if="view.metadata.binding===null">当前只可读取技术状态；当前账户不能据此恢复题目、答案、解析或任务原文。</p><template v-if="view.source"><p aria-label="保持不变的服务端计数">本次固定练习共{{view.source.feedback.question_count}}题：相符{{view.source.feedback.matching_count}}，不同{{view.source.feedback.differing_count}}，明确未作答{{view.source.feedback.unanswered_count}}。</p><template v-if="view.draft"><section v-for="item in view.draft.explanations" :key="item.question_id"><h4>题目{{questionNumber(item.question_id)}}讲解</h4><p>{{item.explanation}}</p><el-button v-for="(citation,i) in item.evidence" :key="i" @click="showEvidence(citation)">核对逐字依据{{i+1}}</el-button></section><section v-for="(item,i) in view.draft.revision_steps" :key="i"><h4>原知识点复习{{i+1}}</h4><p>{{item.explanation}}</p><el-button v-for="(citation,j) in item.evidence" :key="j" @click="showEvidence(citation)">核对复习依据{{j+1}}</el-button></section><section v-for="(item,i) in view.draft.gaps" :key="i"><h4>现有材料缺口{{i+1}}</h4><p>{{item.description}}</p></section></template><p v-else>本状态没有已接受的模型草稿。</p></template></template><el-dialog :model-value="dialogOpen" title="本次教学说明的当前完整依据" :close-on-click-modal="false" :before-close="done=>{closeEvidence();done();}"><template v-if="evidence"><h3>{{evidence.title}}</h3><p>原文引用：</p><blockquote>{{evidence.quote}}</blockquote><details><summary>引文定位详情</summary><p>Unicode码点区间[{{evidence.start}},{{evidence.end}})</p></details><pre>{{evidence.text}}</pre></template></el-dialog></section></template>
<script setup>
import{ref,watch}from'vue';import{useClinicalTrainingSession}from'./useClinicalTrainingSession';import{trainingCanonical,trainingSame}from'@/api/ai/clinicalTrainingCore';import{verifyTrainingTaskMetadata,verifyTrainingTaskParts,getTrainingSharedTask,getTrainingTaskPart}from'@/api/ai/clinicalTrainingTasks';
const props=defineProps({metadata:{type:Object,default:null},parts:{type:Object,default:null},active:{type:Boolean,default:true},configRevision:{type:[String,Number],default:null}}),emit=defineEmits(['invalidate']);const view=ref(null),error=ref(''),busy=ref(false),dialogOpen=ref(false),evidence=ref(null);let epoch=0,dialogEpoch=0;
const states={queued:'排队中',running:'进行中',succeeded:'已接受教学草稿',failed:'失败',cancelled:'已取消'},count=x=>x===null?'未知':String(x),attempt=x=>x===true?'已调用':x===false?'已证明未调用':'未知';
function closeEvidence(){dialogEpoch++;dialogOpen.value=false;evidence.value=null;}
function clear(){epoch++;closeEvidence();view.value=null;busy.value=false;error.value='';}
const session=useClinicalTrainingSession(props,()=>{clear();emit('invalidate');}),clone=x=>JSON.parse(trainingCanonical(x));
async function accept(){clear();if(!session.allowed.value||props.metadata===null)return;const ticket=session.ticket(),e=epoch,current=()=>session.current(ticket)&&epoch===e;busy.value=true;try{const meta=props.metadata,parts=props.parts;if(!verifyTrainingTaskMetadata(meta))throw new Error('教学任务技术闭集无法核对');if(meta.parts_state==='available'){if(!await verifyTrainingTaskParts(meta,parts,{current}))throw new Error('完整四分件、练习计数、Prompt或实际回执无法核对');if(current())view.value={metadata:clone(meta),source:clone(parts.source.value),draft:clone(parts.result.value)};}else{if(parts!==null)throw new Error('技术状态不得夹带不可读原件');if(current())view.value={metadata:clone(meta),source:null,draft:null};}}catch(e){if(current()){view.value=null;error.value=e.message||'当前完整教学反馈不可读';emit('invalidate');}}finally{if(current())busy.value=false;}}
watch(()=>[props.metadata,props.parts],accept,{deep:true,immediate:true,flush:'sync'});
function questionNumber(id){return view.value?.source.lesson.questions.findIndex(x=>x.question_id===id)+1;}
async function showEvidence(citation){closeEvidence();const original=view.value;if(!session.allowed.value||!original?.draft)return;const ticket=session.ticket(),e=epoch,d=dialogEpoch,current=()=>session.current(ticket)&&e===epoch&&d===dialogEpoch&&dialogOpen.value;dialogOpen.value=true;try{const meta=(await getTrainingSharedTask(original.metadata.run_id)).data;if(!current())return;if(!trainingSame(meta,original.metadata))throw new Error('当前任务状态或来源已变化');const parts=Object.fromEntries(await Promise.all(['task','source','binding','result'].map(async name=>[name,await getTrainingTaskPart(meta.run_id,name)])));if(!current())return;if(!await verifyTrainingTaskParts(meta,parts,{current}))throw new Error('当前依据完整性或来源权限失效');if(!current())return;const draft=parts.result.value,all=draft.explanations.flatMap(x=>x.evidence).concat(draft.revision_steps.flatMap(x=>x.evidence));if(!all.some(x=>trainingSame(x,citation)))throw new Error('本次模型草稿未引用此片段');const source=parts.source.value,text=citation.target==='reviewed_rationale'?source.feedback.questions.find(x=>x.question_id===citation.question_id)?.reviewed_rationale:source.references.references.find(x=>x.document_id===citation.document_id)?.content;if(typeof text!=='string'||Array.from(text).slice(citation.start_codepoint,citation.end_codepoint).join('')!==citation.quote)throw new Error('逐字Unicode码点引用不同');evidence.value={title:citation.target==='reviewed_rationale'?'当前受审解析':source.references.references.find(x=>x.document_id===citation.document_id).title,text,quote:citation.quote,start:citation.start_codepoint,end:citation.end_codepoint};}catch(e){if(current()){clear();error.value=e.message||'当前原始依据不可读';emit('invalidate');}}}
</script><style scoped>section{display:grid;gap:12px}pre{white-space:pre-wrap;overflow-wrap:anywhere;max-height:55vh;overflow:auto}blockquote{white-space:pre-wrap}</style>
